    commonName: 'Pallas\'s Cat (Manul)',
    scientificName: 'Otocolobus manul',
    category: 'Mammal',
    region: 'Eastern Ladakh high plateaus (Changthang, Hanle, Tsokar, Nyoma)',
    status: 'Rare',
    habitat: 'Cold, arid, rocky steppe, scree slopes, and boulder fields between 3,800 and 5,300 m.',
    size: '45–65 cm body, 20–30 cm tail; weight 2.5–4.5 kg.',
    conservation: 'Least Concern',
    feature: 'Extremely dense, plush silvery-grey coat, wide-set low ears, and distinctively round pupils (unlike other small cats).',
    funFact: 'Pallas\'s Cat possesses the densest and longest fur of any wild cat in the world, allowing it to comfortably survive temperatures plunging to minus 50 degrees Celsius.',
    distribution: 'High trans-Himalayan valleys of eastern Ladakh, notably Hanle Valley, Tsokar basin, Rangdum, and parts of Zanskar.',
    diet: 'Highly specialized hunter of pikas (Ochotona), voles, snow finches, and chukars.',
