    breeding: 'Breeds in late winter; 2–6 kittens born in rock crevices or abandoned marmot burrows in April–May.',
    threats: 'Secondary poisoning from pika control campaigns, predation by feral dogs, and loss of rocky boulder shelter.',
    ecologicalRole: 'Specialist predator regulating high-altitude pika and small mammal colonies.',
    identification: 'Stocky, stout build with very thick silvery-grey fur tipped with white, flat forehead, low-set rounded ears, and a ringed black-tipped tail.',
    vocalization: 'Combination of high-pitched yelps sounding like a small puppy barking, accompanied by low growls, hisses, and purring.',
