    feature: 'Stout, plump rodent with dense golden-yellow to tawny fur, dark brown cap on head, and massive digging claws.',
    funFact: 'Himalayan Marmots hibernate for up to 7 months continuously under deep snow, dropping their body temperature and slowing their heart rate to just a few beats per minute.',
    distribution: 'Abundant in the high trans-Himalayan valleys of Ladakh, Drass, Zanskar, and high passes above Sonamarg and Gurez.',
    diet: 'Herbivorous; feeds on nutrient-rich alpine grasses, wild herbs, roots, tubers, and flowering plants.',
    behavior: 'Diurnal and highly colonial. Sits upright on hind legs as a sentry outside extensive underground tunnel complexes.',
    breeding: 'Breeds immediately after emerging from hibernation in spring; litters of 2–6 young born in deep nesting chambers.',
    threats: 'Tourist disturbance and feeding, predation by free-ranging feral dogs, and localized poaching.',
