  ZoologySpecies(
    id: 'wild-boar',
    commonName: 'Wild Boar (Indian Wild Boar)',
    scientificName: 'Sus scrofa cristatus',
    category: 'Mammal',
    region: 'Jammu plains, Shivalik foothills, and lower Kashmir Valley',
    status: 'Present',
    habitat: 'Moist deciduous forests, riverine reedbeds, agricultural scrub, and mountain foothill woodlands.',
    size: '110–150 cm length, 70–90 cm shoulder height; weight 70–140 kg.',
    conservation: 'Least Concern',
    feature: 'Stout muscular build with coarse grizzled black-brown bristly coat, erect dorsal crest, and razor-sharp curving canine tusks.',
    funFact: 'The wild boar has an extraordinarily sensitive, cartilaginous snout disc supported by a prenasal bone that allows it to plow through rocky soil and sense subterranean roots over a foot underground.',
    distribution: 'Very common throughout Jammu, Kathua, Udhampur, Samba, Rajouri, and present in lower Dachigam and foothill fringes of Kashmir.',
