    feature: 'Robust, heavily tuberculated warty body with prominent, elongated kidney-shaped parotoid glands behind the eyes.',
    funFact: 'The Himalayan Toad produces a bitter, milky bufotoxin from its parotoid glands that deters mammalian predators, allowing it to survive alongside bears and leopards in subalpine forests.',
    distribution: 'Widely distributed in Gulmarg, Sonamarg, Pahalgam, Dachigam, and forested hills of Jammu division.',
    diet: 'Nocturnal invertebrate predator; eats beetles, slugs, earthworms, moths, ants, and caterpillars.',
    behavior: 'Nocturnal and terrestrial. Spends daytime hidden under damp logs, rotting bark, or flat boulders, emerging at dusk to feed.',
    breeding: 'Breeds in spring (April–June) in clean, shallow meltwater pools; females lay long gelatinous strings of thousands of black eggs.',
    threats: 'Pollution of breeding pools by agricultural pesticides and drying of mountain springs.',
    ecologicalRole: 'Major nocturnal consumer of forest floor invertebrates and bio-indicator of clean freshwater.',
    identification: 'Large brownish-yellow to olive toad with dark-tipped warts, large protruding golden eyes with horizontal pupils, and prominent parotoid glands.',
    vocalization: 'During the spring breeding season, males produce a continuous, rhythmic, low-pitched musical trill or metallic churring: "creeeee-creeeee" echoing from meltwater pools.',
