    scientificName: 'Naemorhedus goral',
    category: 'Mammal',
    region: 'Jammu hills, Pir Panjal, and lower Chenab valley',
    status: 'Present',
    habitat: 'Steep rocky crags, precipitous slopes, and open oak-pine cliff forests at 1,000–3,000 m.',
    size: '95–130 cm body length, 65–75 cm shoulder height; weight 25–35 kg.',
    conservation: 'Near Threatened',
    feature: 'Stout goat-antelope with small backward-pointing conical horns, grey-brown coat, and white throat patch.',
    funFact: 'Himalayan Gorals are extraordinarily agile cliff climbers, leaping between near-vertical rock ledges with specialized rubbery hoof soles.',
    distribution: 'Steep slopes of the Pir Panjal, Kishtwar, Udhampur, Poonch, and Rajouri districts in Jammu division.',
    diet: 'Herbivorous browser and grazer; feeds on mountain grasses, shrubs, forbs, acorns, and dry foliage on rocky bluffs.',
